        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            a, b = obj[0], obj[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return a, b
        return None

    def get_self_pos(obs):
        for k in ("self", "agent", "player", "me"):
            p = as_xy(obs.get(k))
            if p is not None:
                return p
        for k in ("self_pos", "agent_pos", "player_pos", "me_pos", "position", "pos"):
            p = as_xy(obs.get(k))
            if p is not None:
                return p
        return None

    def get_list(obs, keys):
        for k in keys:
            v = obs.get(k)
            if isinstance(v, list):
                return v
        return []

    def extract_targets(items):
        out = []
        for it in items:
            p = as_xy(it)
            if p is None and isinstance(it, dict):
                for kk in ("pos", "position", "loc", "xy"):
                    p = as_xy(it.get(kk))
                    if p is not None:
                        break
            if p is not None:
                out.append(p)
        return out

    def nearest(pos, points):
        best = None
        bd = None
        px, py = pos
        for qx, qy in points:
            d = abs(qx - px) + abs(qy - py)
            if bd is None or d < bd:
                bd = d
                best = (qx, qy)
        return best, bd

    def score_cell(x, y, goal, threats, allies, bias):
        s = 0
        if goal is not None:
            s -= abs(goal[0] - x) + abs(goal[1] - y)
        for tx, ty, w in threats:
            d = abs(tx - x) + abs(ty - y)
            s += w * max(0, 6 - d)
        for ax, ay, w in allies:
            d = abs(ax - x) + abs(ay - y)
            s += w * max(0, 3 - d)
        s += bias.get((x, y), 0)
        return s

