    if pos is None:
        return [0, 0]
    x, y = pos

    resources = extract_targets(get_list(observation, ("resources", "resource_tiles", "food", "collectibles", "items")))
    enemies = extract_targets(get_list(observation, ("enemies", "opponents", "enemy_units", "enemy_agents", "threats")))
    allies = extract_targets(get_list(observation, ("allies", "teammates", "friendly_units", "friends")))
    objectives = extract_targets(get_list(observation, ("targets", "goals", "points", "flags", "bases", "territory")))

