    # General scoring search over 9 moves
    bias = {}
    if "territory" in mode or "control" in mode:
        # Mild preference to expand outward / toward center if known
        cx = observation.get("center_x")
        cy = observation.get("center_y")
        if isinstance(cx, (int, float)) and isinstance(cy, (int, float)):
            center = (cx, cy)
            for sx in (-1, 0, 1):
                for sy in (-1, 0, 1):
