                    bias[(x + sx, y + sy)] = 0.01 * (abs(sx) + abs(sy))
    else:
        for sx in (-1, 0, 1):
            for sy in (-1, 0, 1):
                bias[(x + sx, y + sy)] = 0

    best_move = (0, 0)
    best_score = None
    for sx in (-1, 0, 1):
        for sy in (-1, 0, 1):
            nx, ny = x + sx, y + sy
            s = score_cell(nx, ny, goal, threat_points, ally_points, bias)
            # Prefer staying put only if no better option
            if best_score is None or s > best_score:
                best_score = s
                best_move = (sx, sy)

    return [best_move[0], best_move[1]]

